mapper.insert:
MERGE INTO BOK_SUBJECT a USING (
SELECT #{item.booksetId} BOOKSET_ID, #{item.subjectNo} SUBJECT_NO, #{item.subjectName} SUBJECT_NAME, #{item.fsubjectId} FSUBJECT_ID, #{item.subjectType} SUBJECT_TYPE, #{item.subjectLevel} SUBJECT_LEVEL, #{item.balFlag} BAL_FLAG, #{item.dataSource} DATA_SOURCE, #{item.status} STATUS, #{item.remark} REMARK, #{item.errMsg} ERR_MSG, #{item.createUser} CREATE_USER, #{item.createDept} CREATE_DEPT, #{item.createTime} CREATE_TIME, #{item.updateUser} UPDATE_USER, #{item.updateTime} UPDATE_TIME FROM DUAL
) b ON (a.BOOKSET_ID = b.BOOKSET_ID AND a.SUBJECT_NO = b.SUBJECT_NO) WHEN MATCHED THEN UPDATE SET a.SUBJECT_NAME = b.SUBJECT_NAME, a.FSUBJECT_ID = b.FSUBJECT_ID, a.SUBJECT_TYPE = b.SUBJECT_TYPE, a.SUBJECT_LEVEL = b.SUBJECT_LEVEL, a.BAL_FLAG = b.BAL_FLAG, a.STATUS = b.STATUS, a.REMARK = b.REMARK, a.ERR_MSG = b.ERR_MSG, a.UPDATE_USER = b.UPDATE_USER, a.UPDATE_TIME = b.UPDATE_TIME WHEN NOT MATCHED THEN INSERT(BOOKSET_ID,SUBJECT_NO,SUBJECT_NAME,FSUBJECT_ID,SUBJECT_TYPE,SUBJECT_LEVEL,BAL_FLAG,DATA_SOURCE,STATUS,REMARK,ERR_MSG,CREATE_USER,CREATE_DEPT,CREATE_TIME,UPDATE_USER,UPDATE_TIME) VALUES(b.BOOKSET_ID,b.SUBJECT_NO,b.SUBJECT_NAME,b.FSUBJECT_ID,b.SUBJECT_TYPE,b.SUBJECT_LEVEL,b.BAL_FLAG,b.DATA_SOURCE,b.STATUS,b.REMARK,b.ERR_MSG,b.CREATE_USER,b.CREATE_DEPT,b.CREATE_TIME,b.UPDATE_USER,b.UPDATE_TIME)

mapper.select:
select BS.BOOKSET_ID as booksetId, BS.SUBJECT_NO as subjectNo, BS.SUBJECT_NAME as subjectName, BS.FSUBJECT_ID as fsubjectId, BS.SUBJECT_TYPE as subjectType, BS.SUBJECT_LEVEL as subjectLevel, BS.BAL_FLAG as balFlag, BS.CREATE_USER as createUser, BS.CREATE_DEPT as createDept, BS.CREATE_TIME as createTime, BS.UPDATE_USER as updateUser, BS.UPDATE_TIME as updateTime, BS.UPDATE_TIME as updateDate, BS.DATA_SOURCE as dataSource, BS.STATUS as statusValid, BS.REMARK as remark, BS.ERR_MSG as errMsg from BOK_SUBJECT BS
BS.SUBJECT_LEVEL = #{subjectLevel}
AND BS.BAL_FLAG = #{balFlag}
AND BS.FSUBJECT_ID = #{fsubjectId}
AND BS.SUBJECT_NO like #{subjectNo} || '%'
AND BS.SUBJECT_NAME like '%' || #{subjectName} || '%'
AND BS.SUBJECT_TYPE = #{subjectType}
AND BS.STATUS = #{status}
order by BS.BOOKSET_ID,BS.SUBJECT_NO,BS.SUBJECT_LEVEL

select BS.BOOKSET_ID as booksetId, BS.SUBJECT_NO as subjectNo, BS.SUBJECT_NAME as subjectName, BS.FSUBJECT_ID as fsubjectId,
BS.SUBJECT_TYPE as subjectType, BS.SUBJECT_LEVEL as subjectLevel, BS.BAL_FLAG as balFlag, BS.CREATE_USER as createUser, BS.CREATE_DEPT as createDept, BS.CREATE_TIME as createTime, BS.UPDATE_USER as updateUser, BS.UPDATE_TIME as updateTime, BS.UPDATE_TIME as updateDate, BS.DATA_SOURCE as dataSource, BS.STATUS as statusValid, BS.REMARK as remark, BS.ERR_MSG as errMsg from BOK_SUBJECT BS
SUBJECT_NO = #{subjectNo}
AND BOOKSET_ID = #{booksetId}
